INSERT INTO ghost_type (ghost_id, ghost_name, behavior, hostility, movement_speed, description, weakness) VALUES
  (1, 'Shadow Figure', 'stalker', 'low', 3, 'A man-shaped absence at the edge of your flashlight. It only moves when you are not looking.', 'Steady candlelight'),
  (2, 'White Lady', 'patrol', 'medium', 4, 'A woman in a white gown who walks the same route every night, weeping.', 'A rosary and a lit candle'),
  (3, 'Tiyanak', 'aggressive', 'high', 7, 'It cries like a lost infant to lure you close, then shows its teeth.', 'Salt scattered in a circle'),
  (4, 'Kapre', 'patrol', 'low', 2, 'A giant smoking a cigar in the trees. Mostly curious — until you trespass.', 'An agimat amulet'),
  (5, 'The Head Nurse', 'stalker', 'high', 6, 'Still doing her rounds decades after the ward closed. Her footsteps never stop.', 'Her own photograph, shown by candlelight'),
  (6, 'Manananggal', 'aggressive', 'extreme', 8, 'The upper half hunts on leathery wings; the lower half waits somewhere below.', 'Salt, an agimat, and a blessed rosary');
INSERT INTO haunted_places (place_id, place_name, difficulty, atmosphere, is_unlocked, description) VALUES
  (1, 'Old Dormitory', 'easy', 'flickering', TRUE, 'A shuttered student dorm. Viewers swear a figure stands behind you in every stream.'),
  (2, 'Balete Road Mansion', 'medium', 'misty', FALSE, 'A colonial-era house swallowed by balete trees. Drivers report a lady in white on the road.'),
  (3, 'St. Agatha Hospital Ward', 'medium', 'sterile', FALSE, 'Closed in 1974. The call bells in Ward C still ring at 3 a.m.'),
  (4, 'Sunken Chapel', 'hard', 'flooded', FALSE, 'Half underwater since the typhoon. Something with wings nests in the bell tower.');
INSERT INTO items (item_id, item_name, item_type, description) VALUES
  (1, 'Sea Salt Pouch', 'ritual_salt', 'Coarse salt in a cloth pouch. Ghosts cannot cross a line of it.'),
  (2, 'Rosary', 'relic', 'Worn wooden beads, warm to the touch.'),
  (3, 'Old Photograph', 'relic', 'A faded staff portrait. One face has been scratched out.'),
  (4, 'Vigil Candle', 'candle', 'A tall white candle. The flame leans toward spirits.'),
  (5, 'Agimat Amulet', 'talisman', 'A carved charm inscribed with old protective words.');
